#include "stdlib/lapack/base/dgbtf2.h"
#include "stdlib/lapack/base/shared.h"
#include <stdio.h>
#include <stdlib.h>

/**
* Main execution sequence.
*/
int main( void ) {
	double AB[] = {
		999.0, 999.0, 999.0, 999.0,
		999.0, 2.0, 2.0, 1.0,
		1.0, 3.0, 5.0, 7.0,
		-4.0, 2.0, 3.0, 999.0
	};
	double B[] = { 9.0, 0.0, 2.0, 0.0, 9.0 };
	LAPACK_INT PIV[ 4 ] = { -99, -99, -99, -99 };
	LAPACK_INT P[ 5 ] = { 8, -99, -99, -99, 8 };
	LAPACK_INT info;

	// Pivot entries record individual swaps, so repeated values are valid:
	info = API_SUFFIX(c_dgbtf2)( LAPACK_ROW_MAJOR, 4, 4, 1, 1, AB, 4, PIV );
	if (
		info != 0 || PIV[ 0 ] != 2 || PIV[ 1 ] != 2 ||
		PIV[ 2 ] != 3 || PIV[ 3 ] != 4 ||
		AB[ 8 ] != -4.0 || AB[ 12 ] != -0.25 ||
		AB[ 0 ] != 999.0 || AB[ 1 ] != 999.0 || AB[ 15 ] != 999.0
	) {
		fprintf( stderr, "Unexpected band factorization.\n" );
		return EXIT_FAILURE;
	}
	printf( "INFO: %d; stepwise PIV: %d, %d, %d, %d\n", (int)info, (int)PIV[ 0 ], (int)PIV[ 1 ], (int)PIV[ 2 ], (int)PIV[ 3 ] );

	// A first zero pivot does not suppress later steps; signed views preserve guards:
	info = API_SUFFIX(c_dgbtf2_ndarray)( 3, 3, 0, 0, B, 1, -1, 3, P, -1, 3 );
	if (
		info != 1 || P[ 0 ] != 8 || P[ 1 ] != 3 || P[ 2 ] != 2 ||
		P[ 3 ] != 1 || P[ 4 ] != 8 ||
		B[ 0 ] != 9.0 || B[ 1 ] != 0.0 || B[ 2 ] != 2.0 ||
		B[ 3 ] != 0.0 || B[ 4 ] != 9.0
	) {
		fprintf( stderr, "Unexpected strided singular factorization.\n" );
		return EXIT_FAILURE;
	}
	printf( "Strided INFO: %d; guarded PIV: %d, %d, %d, %d, %d\n", (int)info, (int)P[ 0 ], (int)P[ 1 ], (int)P[ 2 ], (int)P[ 3 ], (int)P[ 4 ] );
	return EXIT_SUCCESS;
}
